import sys
import math

def clean(a):
    for i in range(len(a) - 1, -1, -1):
        if a[i] != 0:
            return a[:i+1]
    return []

def mulnaive(a, b):
    c = [0] * (len(a) + len(b) - 1)
    big = 8 * 998244353 * 998244353
    for i in range(len(a)):
        for j in range(len(b)):
            c[i + j] += a[i] * b[j]
            if c[i + j] >= big:
                c[i + j] -= big
    for i in range(len(c)):
        c[i] %= 998244353
    return c

def pow_mod(a, n, mod):
    ret = 1
    for x in range(63 - (n.bit_length() - 1), -1, -1):
        ret = ret * ret % mod
        if (n << (63 - x)) & (1 << 63):
            ret = ret * a % mod
    return ret

def invl(a, mod):
    b = mod
    p = 1
    q = 0
    while b > 0:
        c = a // b
        d = a
        a = b
        b = d % b
        d = p
        p = q
        q = d - c * q
    return p % mod

def nttmb(src, n, inverse, P, g):
    dst = src[:]
    h = n.bit_length() - 1
    K = 1 << (h + 1)
    H = (K.bit_length() - 1) * 2
    M = (K * K) // P
    wws = [0] * (1 << (h - 1))
    dw = pow_mod(g, P - 1 - (P - 1) // n, P) if inverse else pow_mod(g, (P - 1) // n, P)
    w = (1 << 32) % P
    for k in range(1 << (h - 1)):
        wws[k] = w
        w = (w * dw) % P
    J = invl(1 << 32, P)
    for i in range(h):
        for j in range(1 << i):
            s = j << (h - i)
            t = s | (1 << (h - i - 1))
            for k in range(1 << (h - i - 1)):
                u = (dst[s + k] - dst[t + k] + 2 * P) * wws[k] % P
                dst[s + k] += dst[t + k]
                if dst[s + k] >= 2 * P:
                    dst[s + k] -= 2 * P
                Q = ((u << 32) * J) >> 32
                dst[t + k] = (u >> 32) - (Q * P >> 32) + P
        if i < h - 1:
            for k in range(1 << (h - i - 2)):
                wws[k] = wws[k * 2]
    for i in range(n):
        if dst[i] >= P:
            dst[i] -= P
    for i in range(n):
        rev = int('{:032b}'.format(i)[::-1], 2) >> (32 - h)
        if i < rev:
            dst[i], dst[rev] = dst[rev], dst[i]
    if inverse:
        in_val = invl(n, P)
        for i in range(n):
            dst[i] = (dst[i] * in_val) % P
    return dst

def convoluteSimply(a, b, P, g):
    m = max(2, 1 << (max(a.__len__(), b.__len__()) - 1).bit_length() + 1)
    fa = nttmb(a, m, False, P, g)
    fb = fa if a is b else nttmb(b, m, False, P, g)
    for i in range(m):
        fa[i] = fa[i] * fb[i] % P
    return nttmb(fa, m, True, P, g)

def main():
    input = sys.stdin.read().split()
    n = int(input[0])
    K = int(input[1])
    d = list(map(int, input[2:2+K]))
    line_idx = 2 + K
    f = [0] * 20
    for i in range(K):
        for j in range(K):
            f[10 + d[i] - d[j]] += 1
    n //= 2
    g = [1]
    for D in range(17, -1, -1):
        g = clean(convoluteSimply(g, g, 998244353, 3))
        if (n << (~D)) < 0:
            g = clean(mulnaive(g, f))
    print(g[n * 10] if n * 10 < len(g) else 0)

if __name__ == "__main__":
    main()

